<template><div class="app-container"><el-form :inline="true" :model="form"><el-form-item label="已通过订单ID"><el-input v-model="form.orderId" placeholder="请输入订单ID" /></el-form-item><el-form-item><el-button type="primary" @click="load">加载订单明细</el-button></el-form-item></el-form><el-form v-if="lines.length" :model="form" label-width="100px"><el-form-item label="仓库ID"><el-input v-model="form.warehouseId" placeholder="请输入启用仓库ID" /></el-form-item><el-form-item label="入库日期"><el-date-picker v-model="form.businessDate" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-table :data="lines" border><el-table-column prop="itemSnapshot" label="商品" /><el-table-column prop="orderQuantity" label="订单数量" /><el-table-column prop="receivedQuantity" label="已入库" /><el-table-column prop="remainingQuantity" label="剩余可入库" /><el-table-column label="本次入库"><template #default="s"><el-input-number v-model="s.row.quantity" :min="0" :precision="4" :max="Number(s.row.remainingQuantity)" /></template></el-table-column></el-table><el-button class="mt8" type="primary" @click="confirm">确认入库</el-button></el-form></div></template>
<script setup lang="ts" name="SupplyReceipt">
import { confirmReceipt, prepareReceipt } from '@/api/supply'
const { proxy } = getCurrentInstance()!; const form = reactive({ orderId: '', warehouseId: '', businessDate: '', remark: '' }); const lines = ref<any[]>([])
async function load() { if (!form.orderId) return proxy.$modal.msgError('订单ID不能为空'); const res = await prepareReceipt(form.orderId); lines.value = (res.data?.lines || []).map((line: any) => ({ ...line, quantity: 0 })) }
async function confirm() { const selected = lines.value.filter(line => Number(line.quantity) > 0).map(line => ({ orderLineId: line.orderLineId, quantity: line.quantity })); if (!selected.length) return proxy.$modal.msgError('至少填写一条入库数量'); await confirmReceipt({ orderId: form.orderId, warehouseId: form.warehouseId, businessDate: form.businessDate, remark: form.remark, lines: selected }); proxy.$modal.msgSuccess('入库确认成功'); load() }
</script>
